public ExcuteResult TransferLoadBeltToDispense(bool isManual = false)
        {
            try
            {
            retry:
                if (this.TransportProgram.DispenseSubSectionProgram.SubSectionState ==
                    SubSectionStateEnum.HasMaterial)
                {
                    // 如果不满足条件
                    return ExcuteResult.NoStart;
                }

                // 联机
                if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online)
                {
                    // 如果Loading段无料
                    if (this.TransportProgram.LoadingSubSectionProgram.SubSectionState ==
                        SubSectionStateEnum.NoMaterial)
                    {
                        Thread.Sleep(50);
                        return ExcuteResult.NoStart;
                    }
                }

                // 开始尝试传送产品
                this.TransportProgram.LoadingSubSectionProgram.SubSectionTransferState =
                    SubSectionStateTransferEnum.Transfering;

                // 按时间传送， 时间配置在参数里
                InOutPutBeltSetting inOutPutBeltSetting = TransportProgram.LoadingSubSectionProgram.InOutPutBeltSetting;

                if (inOutPutBeltSetting == null)
                {
                    DialogResult dr = AKRSMessageBoxExt.Show(
                        @"进料皮带数据集不存在\r\n
                          重试 : 重新进料
                          终止 :  退出工作
                          忽略:  忽略此异常 ",
                        $"报警",
                        new[] { "重试", "终止", "忽略" },
                        new[] { DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore },
                        AlarmLevel.FirstLevel);

                    switch (dr)
                    {
                        case DialogResult.Retry:
                            goto retry;

                        case DialogResult.Abort:
                            return ExcuteResult.Abort;

                        case DialogResult.Ignore:
                            break;
                    }
                }

                List<Task> tasks = new List<Task>();
                tasks.Add(Task.Run(
                    () =>
                        {
                            // 点胶气缸1顶起，准备接料
                            this.DispenseSubSectionController.BlockCylinder1UpAndDelay(10);
                        }));

                tasks.Add(Task.Run(
                    this.DispenseSubSectionController.UnClamp));

                // 点胶气缸2顶起，准备接料
                // this.DispenseSubSectionController.BlockCylinder1UpAndDelay(20);

                // 等待所有任务完成
                Task.WaitAll(tasks.ToArray());

                // 皮带1转动
                this.LoadingSubSectionController.MoveBeltNoWaitArrive();

                Thread.Sleep(200);

                bool hasMaterialInModule = false;

                // 如果 A传感器 没感应到，则报警（载台1 无料）
                while (this.LoadingSubSectionController.IsMoving())
                {
                    // 判断传感器是否感应到有料
                    hasMaterialInModule = this.LoadingSubSectionController.HasMaterialInModule();

                    // 如果感应到了 则跳出循环
                    if (hasMaterialInModule)
                    {
                        // 生成一个Transport Unit 对象
                        if (this.TransportProgram.LoadingSubSectionProgram.TransportUnit == null)
                        {
                            this.TransportProgram.LoadingSubSectionProgram.TransportUnit =
                                new TransportUnitSystem.Module.Matter.TransportUnit("上料载具对象生成");

                            this.TransportProgram.Save();
                        }

                        if (this.TransportProgram.LoadingSubSectionProgram.TransportUnit == null)
                        {
                            Machine.GetInstance().Stop();

                            throw new Exception("create transport unit fail");
                        }

                        break;
                    }

                    Thread.Sleep(30);
                }

                // 如果载台都转动到位 且传感器A还没有感应到 则报警
                if (hasMaterialInModule == false)
                {
                    if (isManual == false)
                    {
                        this.TransportProgram.LoadingSubSectionProgram.SubSectionState =
                            SubSectionStateEnum.NoMaterial;

                        // 报警 载台1 无料
                        DialogResult dr = AKRSMessageBoxExt.Show(
                                $"检测到进料载台无料！ \r\n",
                                "报警",
                                new[] { "重新上料", "不再上料", "终止" },
                                new DialogResult[]
                                    {
                                        DialogResult.Retry, DialogResult.Cancel,DialogResult.Abort
                                    },
                                AlarmLevel.SecondLevel);

                        switch (dr)
                        {
                            case DialogResult.Retry:
                                goto retry;

                            case DialogResult.Cancel:

                                // 关闭持续上料
                                TransportProvider.ContinuousFeeding = false;
                                return ExcuteResult.NoStart;

                            case DialogResult.Abort:
                                return ExcuteResult.Abort;
                        }
                    }
                    else
                    {
                        // 手动模式 不需要报警
                        return ExcuteResult.None;
                    }
                }

                // 修改点胶传料状态
                this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
                    SubSectionStateTransferEnum.Transfering;

                // 点胶皮带 转动
                this.DispenseSubSectionController.MoveBeltNoWaitArrive();
                Thread.Sleep(200);

                while (this.DispenseSubSectionController.IsMoving())
                {
                    // 物料检测（传感器C） 
                    hasMaterialInModule = this.DispenseSubSectionController.HasMaterialInModule();

                    // 如果 C 感应到了 则跳出循环
                    if (hasMaterialInModule)
                    {
                        break;
                    }

                    Thread.Sleep(200);
                }

                // 皮带转完了 或者C感应到了 跳出循环
                // 如果 C没感应到则说明是皮带转完了停下来的
                if (hasMaterialInModule == false)
                {
                    this.TransportProgram.DispenseSubSectionProgram.SubSectionState =
                        SubSectionStateEnum.NoMaterial;

                    this.DispenseSubSectionController.BlockCylinder1DownAndDelay(50);

                    this.TransportProgram.LoadingSubSectionProgram.SubSectionTransferState =
                            SubSectionStateTransferEnum.Alarm;

                    this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
                            SubSectionStateTransferEnum.Alarm;

                    // 如果B感应到，则报警：点胶台进料卡料
                    DialogResult dr = AKRSMessageBoxExt.Show(
                            @"点胶载台卡料
                              点击
                              重试 : 重新上料
                              终止 ：退出工作
                              忽略: 忽略此报警",
                            $"报警",
                            new[] { "重试", "终止", "忽略" },
                            new[] { DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore });

                    switch (dr)
                    {
                        case DialogResult.Abort:
                            // 停止
                            return ExcuteResult.Abort;

                        case DialogResult.Retry:
                            goto retry;

                        case DialogResult.Ignore:
                            break;
                    }
                }
                else // C 感应到了
                {
                    // 是C感应到 才停下来的
                    while (this.DispenseSubSectionController.IsMoving())
                    {
                        Thread.Sleep(500);
                    }

                    // 物料检测（传感器C） 
                    hasMaterialInModule = this.DispenseSubSectionController.HasMaterialInModule();

                    if (hasMaterialInModule)
                    {
                        this.TransportProgram.LoadingSubSectionProgram.SubSectionTransferState =
                            SubSectionStateTransferEnum.Alarm;

                        this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
                            SubSectionStateTransferEnum.Alarm;

                        // 如果B 感应到，则报警：点胶料台入料卡料
                        DialogResult dr = AKRSMessageBoxExt.Show(
                            @"点胶载台卡料
                              点击
                              重试 : 重新上料
                              终止 ：退出工作
                              忽略: 忽略此报警",
                            $"报警",
                            new[] { "重试", "终止", "忽略" },
                            new[] { DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore });

                        switch (dr)
                        {
                            case DialogResult.Abort:
                                // 停止
                                return ExcuteResult.Abort;

                            case DialogResult.Retry:
                                goto retry;

                            case DialogResult.Ignore:
                                break;
                        }
                    }

                    this.LoadingSubSectionController.StopMove();

                    // 没配置系统1 气缸就不降落
                    if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
                    {
                        // 传输成功 
                        // 顶升气缸降落
                        this.DispenseSubSectionController.Clamp(true);
                    }


                    this.TransportProgram.DispenseSubSectionProgram.TransportUnit =
                        this.TransportProgram.LoadingSubSectionProgram.TransportUnit;

                    this.TransportProgram.DispenseSubSectionProgram.TransportUnit.Refresh();

                    this.TransportProgram.DispenseSubSectionProgram.SubSectionState =
                        SubSectionStateEnum.HasMaterial;

                    this.TransportProgram.LoadingSubSectionProgram.TransportUnit = null;

                    // 修改记忆状态
                    this.TransportProgram.LoadingSubSectionProgram.SubSectionState =
                        SubSectionStateEnum.NoMaterial;

                    this.TransportProgram.LoadingSubSectionProgram.SubSectionTransferState =
SubSectionStateTransferEnum.Ready;
                    this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
               SubSectionStateTransferEnum.Ready;

                    // 点胶传送到位
                    this.TransportProgram.DispenseSubSectionProgram.IsTuInDispense1 = true;
                }
            }
            catch (Exception ex)
            {
                LogHelper.Post(Level.Error, $"产品传入点胶载台出现异常 ", ex, LogCategory.Transport);

                AKRSXtraMessageBox.Show(
                    $@"产品传入点胶载台出现异常: \r\n
                                          Exception message:{ex.Message} \r\n
                                          StackTrace: {ex.StackTrace}",
                    "Exception",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Error);

                return ExcuteResult.Exception;
            }

            return ExcuteResult.Success;
        }

public override void MoveBeltNoWaitArrive()
        {
            // 按时间传送， 时间配置在参数里
            InOutPutBeltSetting inOutPutBeltSetting = this.loadingSubSectionProgram.InOutPutBeltSetting;

            if (inOutPutBeltSetting == null)
            {
                throw new Exception("进料/出料数据集不存在");
            }

            double transportDistance = inOutPutBeltSetting.ForwardTransportDistance;

            // 皮带1相对运动指令
            this.loadingSubSectionModule.SendRelativeMoveCommandBelt(transportDistance, inOutPutBeltSetting.ForwardVelRate);
        }

public override bool HasMaterialInModule()
        {
            return this.MaterialExistEndSensor.CheckStateForNums(true, 1, 0);
        }

public void SetLoadingTableNeedTabletSignal(bool isNeedTablet)
        {
            this.loadingSubSectionModule.SetLoadingTableNeedTabletSignal(isNeedTablet);
        }

public void SetLoadingTableNeedTabletSignal(bool isNeedTablet)
        {
            this.LoadingTableNeedTabletSignal.SetOutputValue(isNeedTablet);
        }

public override bool HasMaterialInModule()
        {
            return this.MaterialExistSensor.CheckStateForNums(true, 1, 0);
        }

public TransportUnit(string reason)
        {
            this.reason = reason;
            this.BaseInfo = new TransportUnitInfo();
            this.Init();
            this.Name = DateTime.Now.ToString("yyMMddHHmmssfff");
            this.reason = reason;
        }

public TransportUnit()
        {
        }

private void Init()
        {
            this.OppositeSex = ProductConfiguration.GetInstance().OppositeSexConfiguration.OppositeSexConfigs;
            this.InitTransportUnitCoordinateSystem();

            if (ProductConfiguration.GetInstance().TransportUnitConfig.IsOppositeSex)
            {
                this.InitSubstrateByOppositeSex();
            }
            else
            {
                this.InitSubstrateCoordinateSystem();
            }

            TuService.ModifyMatter(this, ProductConfiguration.GetInstance().OtherConfig);

            System2Domain.GetInstance().ActionNodesService.InjectSteps(this);
            System1Domain.GetInstance().ActionNodeController.InjectSteps(this);
        }

public void Refresh()
        {
            this.InitTransportUnitCoordinateSystem();
            this.RefreshSubstrate();
            this.ClearVision();
            this.ClearMeasureHeight();
            this.TransportUnitInfo.IsSystem1Offset = false;
            this.TransportUnitInfo.IsSystem2Offset = false;
        }

public void Clamp(bool isAdditionVc = false)
        {
            if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated == false)
            {
                return;
            }

            if (this.dispenseSubSectionProgram.TransportBeltSetting == null)
            {
                DialogResult dialog = AKRSMessageBoxExt.Show(
                    $"传输系统皮带设置为空，夹紧夹爪失败!\r\n请先设置传输皮带参数！",
                    "报警",
                    new string[] { "确认" },
                    new DialogResult[] { DialogResult.OK });

                return;
            }

        RetryCommand:
            switch (this.dispenseSubSectionProgram.TransportBeltSetting.ClampMode)
            {
                case ClampModeEnum.Lowering:
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.BeforeClampingDelay);
                    this.dispenseSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(true);
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.AfterClampingDelay);
                    break;

                case ClampModeEnum.Vacuum:
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.BeforeClampingDelay);
                    this.dispenseSubSectionModule.SubstrateVaccumElectric.SetOutputValue(true);

                    if (this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric != null && isAdditionVc)
                    {
                        this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric.SetOutputValue(true);
                    }

                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.AfterClampingDelay);
                    break;

                case ClampModeEnum.LoweringAndVacuum:
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.BeforeClampingDelay);
                    this.dispenseSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(true);
                    this.dispenseSubSectionModule.SubstrateVaccumElectric.SetOutputValue(true);
                    if (this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric != null && isAdditionVc)
                    {
                        this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric.SetOutputValue(true);
                    }
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.AfterClampingDelay);
                    break;

                case ClampModeEnum.VacuumAndLowering:
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.BeforeClampingDelay);
                    this.dispenseSubSectionModule.SubstrateVaccumElectric.SetOutputValue(true);
                    this.dispenseSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(true);
                    if (this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric != null && isAdditionVc)
                    {
                        this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric.SetOutputValue(true);
                    }
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.AfterClampingDelay);
                    break;
            }

            Thread.Sleep(500);

            bool ret1 = this.dispenseSubSectionModule.TrackFrontCylinder1PLSensor.GetInputValue();
            bool ret2 = this.dispenseSubSectionModule.TrackFrontCylinder2PLSensor == null
                        || this.dispenseSubSectionModule.TrackFrontCylinder2PLSensor.GetInputValue();
            bool ret3 = this.dispenseSubSectionModule.TrackBackCylinder1PLSensor == null
                        || this.dispenseSubSectionModule.TrackBackCylinder1PLSensor.GetInputValue();

            if ((ret1 && ret2 && ret3) == false)
            {
                DialogResult dialog = AKRSMessageBoxExt.Show(
                    $"点胶工作台气缸夹紧失败，请检查传感器状态！  \r\n",
                    "Alarm",
                    new string[] { "重试", "忽略", "终止" },
                    new DialogResult[] { DialogResult.Retry, DialogResult.Ignore, DialogResult.Abort, });

                switch (dialog)
                {
                    case DialogResult.Retry:
                        goto RetryCommand;

                    // 终止
                    case DialogResult.Abort:
                        Machine.GetInstance().Stop();
                        return;

                    // 忽略
                    case DialogResult.Ignore:
                        break;
                }

               // throw new Exception("点胶夹紧失败, 请检查传感器状态");
            }
        }

public void Start()
        {
            #region 送板机到入料段(联机)

            // 联机
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online
                || MachineHardwareConfiguration.GetInstance().LoadConfiguration
                == LoadConfigurationEnum.OnlineWithAutoLoader)
            {
                if (this.transferAutoLoaderToLoadingBeltTask == null
                    || this.transferAutoLoaderToLoadingBeltTask.Status != TaskStatus.Running)
                {
                    this.transferAutoLoaderToLoadingBeltTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("送板机传入料段线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 如果在单片上料模式下，没有准备好的料片，就继续等待
                                if (!TransportProvider.PrepareFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                ExcuteResult ret = this.transportController.TransferAutoLoaderToLoading();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(500);
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;

                                        break;
                                }

                                Thread.Sleep(500);
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"送板机传入料段线程：{ex.Message}");
                        }
                    });
                    this.transferAutoLoaderToLoadingBeltTask.ConfigureAwait(false);
                }
            }

            #endregion

            #region 入料段到点胶

            // 未配置自动上下料
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.None)
            {
                if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                           == SubSectionStateEnum.HasMaterial)
                {
                    DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                        @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                        $"Warning",
                        new[] { "Yes", "No" },
                        new[] { DialogResult.Yes, DialogResult.No });

                    switch (dr)
                    {
                        case DialogResult.Yes:
                            SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                            break;

                        case DialogResult.No:
                            Machine.GetInstance().Stop();
                            break;
                    }
                }
            }
            else if (MachineHardwareConfiguration.GetInstance().LoadConfiguration != LoadConfigurationEnum.LoaderBin)
            {
                // 皮带上料
                // 防止线程多次启动
                if (this.transferLoadBeltToDispense1Task == null || this.transferLoadBeltToDispense1Task.Status != TaskStatus.Running)
                {
                    this.transferLoadBeltToDispense1Task = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("入料皮带传入点胶1线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                    }
                                }

                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                            @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                            $"Warning",
                                            new[] { "Yes", "No" },
                                            new[] { DialogResult.Yes, DialogResult.No });

                                        switch (dr)
                                        {
                                            case DialogResult.Yes:
                                                SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                                break;

                                            case DialogResult.No:
                                                Machine.GetInstance().Stop();
                                                break;
                                        }
                                    }

                                    continue;
                                }

                                // 如果在连续上料模式下，客户点击了不在上料，就继续等待
                                if (!TransportProvider.ContinuousFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                ExcuteResult ret = this.transportController.TransferLoadBeltToDispense();

                                // 如果有料 直接发信号
                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:
                                        // 传送到点胶1结束
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;
                                        break;
                                }

                                if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated == false)
                                {
                                    SignalPool.GetInstance().AllowDispenseTransferToBondSignal.Set();
                                }

                                Thread.Sleep(100);
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"入料传入点胶1线程异常：{ex.Message}");
                        }
                    });

                    this.transferLoadBeltToDispense1Task.ConfigureAwait(false);
                }
            }
            else
            {
                // 配置自动上下料
                // 防止线程多次启动
                if (this.transferLoaderBinToDispense1Task == null || this.transferLoaderBinToDispense1Task.Status != TaskStatus.Running)
                {
                    this.transferLoaderBinToDispense1Task = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("上料仓传入点胶1线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                    }
                                }

                                if (firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                            @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                            $"Warning",
                                            new[] { "Yes", "No" },
                                            new[] { DialogResult.Yes, DialogResult.No });

                                        switch (dr)
                                        {
                                            case DialogResult.Yes:
                                                SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                                break;

                                            case DialogResult.No:
                                                Machine.GetInstance().Stop();
                                                break;
                                        }
                                    }

                                    continue;
                                }

                                // 点击不再上料就一直等待
                                if (!TransportProvider.ContinuousFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                // 等允许推料信号
                                if (!SignalPool.GetInstance().LoaderAllowPushSignal.Wait())
                                {
                                    return;
                                }

                                // 推料到点胶
                                ExcuteResult ret = this.transportController.TransferLoadBinToDispense();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(500);
                                        continue;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        return;

                                    case ExcuteResult.Success:

                                        // 传料完成
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;
                                        break;

                                    case ExcuteResult.Exception:
                                        Machine.GetInstance().Stop();
                                        return;

                                    // 下一片
                                    case ExcuteResult.None:
                                        break;
                                }

                                // 手动复位
                                SignalPool.GetInstance().LoaderAllowPushSignal.ReSet();

                                // 允许料仓移动
                                SignalPool.GetInstance().AllowLoaderMoveSignal.Set();
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"入料仓传入点胶1线程异常：{ex.Message}");
                        }
                    });

                    this.transferLoaderBinToDispense1Task.ConfigureAwait(false);
                }
            }

            #endregion

            #region 点胶1 传到 点胶2
            if (this.transferDispense1ToDispense2Task == null || this.transferDispense1ToDispense2Task.Status != TaskStatus.Running)
            {
                // 本次节点先不用， 下一迭代 加上
                this.transferDispense1ToDispense2Task = Task.Run(() =>
                {
                    CommonUtil.SetCurrentThreadName("点胶1传入点胶2线程");

                    try
                    {
                        while (Signal.WaitStart())
                        {
                            ExcuteResult ret = this.transportController.TransferDispense1ToDispense2();

                            switch (ret)
                            {
                                case ExcuteResult.NoStart:
                                    Thread.Sleep(500);
                                    break;

                                case ExcuteResult.Abort:
                                    Machine.GetInstance().Stop();
                                    break;

                                case ExcuteResult.Success:
                                    // 给Bond 域发信号, Bond轨道传送完成
                                    SignalPool.GetInstance().TransferToDispense2FinishedSignal.Set();
                                    break;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        AKRSXtraMessageBox.Show($"点胶1传入点胶2线程：{ex.Message}");
                    }
                });
                this.transferDispense1ToDispense2Task.ConfigureAwait(false);
            }
            #endregion

            if (this.transferDispenseToBondTask == null || this.transferDispenseToBondTask.Status != TaskStatus.Running)
            {
                this.transferDispenseToBondTask = Task.Run(() =>
                {
                    CommonUtil.SetCurrentThreadName("点胶传入Bond线程");

                    bool firstStart = true;
                    try
                    {
                        // 正在工作
                        while (Signal.WaitStart())
                        {
                            // 第一次启动时，如果dispense table上有料 则直接开始干
                            if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                            {
                                firstStart = false;
                                if (TransportProgram.GetInstance().BondSubSectionProgram.SubSectionState
                                    == SubSectionStateEnum.HasMaterial)
                                {
                                    SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                }
                            }

                            // 第一次启动时，如果Bond table上有料 则直接开始干
                            if (firstStart)
                            {
                                firstStart = false;
                                if (TransportProgram.GetInstance().BondSubSectionProgram.SubSectionState
                                    == SubSectionStateEnum.HasMaterial)
                                {
                                    DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                        @" 检测到Bond载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                        $"Warning",
                                        new[] { "Yes", "No" },
                                        new[] { DialogResult.Yes, DialogResult.No });

                                    switch (dr)
                                    {
                                        case DialogResult.Yes:
                                            SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                            break;

                                        case DialogResult.No:
                                            Machine.GetInstance().Stop();
                                            break;
                                    }
                                }

                                continue;
                            }


                            ExcuteResult ret = this.transportController.TransferDispenseToBond();

                            switch (ret)
                            {
                                case ExcuteResult.NoStart:
                                    // 提速先注释掉
                                    //Thread.Sleep(50);
                                    break;

                                case ExcuteResult.Abort:
                                    Machine.GetInstance().Stop();
                                    break;

                                case ExcuteResult.Success:
                                    // 给Bond 域发信号, Bond轨道传送完成
                                    SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                    break;
                            }

                            Thread.Sleep(50);
                        }
                    }
                    catch (Exception ex)
                    {
                        AKRSXtraMessageBox.Show($"点胶传入Bond线程：{ex.Message}");
                    }
                });
                this.transferDispenseToBondTask.ConfigureAwait(false);
            }

            if (this.transferBondToWaitingUnloadTask == null || this.transferBondToWaitingUnloadTask.Status != TaskStatus.Running)
            {
                this.transferBondToWaitingUnloadTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("Bond传入等待区线程");

                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                ExcuteResult ret = this.transportController.TransferBondToWaitingUnload();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:

                                        break;

                                    case ExcuteResult.Abort:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Abort");

                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Success");
                                        break;

                                    case ExcuteResult.Exception:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Exception");
                                        Machine.GetInstance().Stop();
                                        break;
                                }

                                Thread.Sleep(100);
                            }
                        }
                        catch (Exception ex)
                        {
                            TransportProvider.RecordTime("Bond传入等待区线程异常", $"{ex.Message}");
                            AKRSXtraMessageBox.Show($"Bond传入等待区线程异常：{ex.Message}");
                        }
                    });
                this.transferBondToWaitingUnloadTask.ConfigureAwait(false);
            }

            #region 等待区到出料

            // 未配置自动上下料
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.None)
            {
                return;
            }
            else if (MachineHardwareConfiguration.GetInstance().LoadConfiguration != LoadConfigurationEnum.LoaderBin)
            {
                if (this.transferWaitingUnloadToUnloadBeltTask == null || this.transferWaitingUnloadToUnloadBeltTask.Status != TaskStatus.Running)
                {
                    this.transferWaitingUnloadToUnloadBeltTask = Task.Run(
                        () =>
                            {
                                CommonUtil.SetCurrentThreadName("等待区传入出料区线程");
                                try
                                {
                                    while (Signal.WaitStart())
                                    {
                                        ExcuteResult ret = this.transportController.TransferWaitingUnloadToUnloadBelt();

                                        switch (ret)
                                        {
                                            case ExcuteResult.NoStart:

                                                break;

                                            case ExcuteResult.Abort:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Abort");

                                                Machine.GetInstance().Stop();

                                                TransportProvider.RecordTime("等待区传入出料区线程", "设备停止");
                                                break;

                                            case ExcuteResult.Success:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Success");
                                                break;

                                            case ExcuteResult.Exception:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Exception");

                                                Machine.GetInstance().Stop();
                                                break;
                                        }

                                        Thread.Sleep(100);
                                    }
                                }
                                catch (Exception ex)
                                {
                                    AKRSXtraMessageBox.Show($"等待区传入出料区线程：{ex.Message}");
                                }
                            });
                    this.transferWaitingUnloadToUnloadBeltTask.ConfigureAwait(false);
                }
            }
            else   // 配置自动上下料
            {
                if (this.transferWaitingUnloadToUnloadBinTask == null || this.transferWaitingUnloadToUnloadBinTask.Status != TaskStatus.Running)
                {
                    this.transferWaitingUnloadToUnloadBinTask = Task.Run(
                        () =>
                        {
                            CommonUtil.SetCurrentThreadName("等待区传入下料仓线程");
                            bool firstStart = true;
                            try
                            {
                                // 正在工作
                                while (Signal.WaitStart())
                                {
                                    // 等允许推料信号
                                    if (!SignalPool.GetInstance().UnloaderAllowPushSignal.Wait())
                                    {
                                        return;
                                    }

                                    // 推料到下料仓
                                    ExcuteResult ret = this.transportController.TransferWaitingUnloadToUnloadBin();

                                    switch (ret)
                                    {
                                        case ExcuteResult.NoStart:
                                            Thread.Sleep(500);
                                            continue;

                                        case ExcuteResult.Abort:
                                            Machine.GetInstance().Stop();
                                            return;

                                        case ExcuteResult.Success:
                                            break;

                                        case ExcuteResult.Exception:
                                            Machine.GetInstance().Stop();
                                            return;
                                    }

                                    Thread.Sleep(200);

                                    // 手动复位
                                    SignalPool.GetInstance().UnloaderAllowPushSignal.ReSet();

                                    // 允许下料仓移动
                                    SignalPool.GetInstance().AllowUnloaderMoveSignal.Set();
                                }
                            }
                            catch (Exception ex)
                            {
                                AKRSXtraMessageBox.Show($"等待区传入下料仓线程：{ex.Message}");
                            }
                        });
                    this.transferWaitingUnloadToUnloadBinTask.ConfigureAwait(false);
                }
            }

            #endregion

            #region 出料段到收板机(联机)

            // 联机
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online || MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.OnlineWithAutoUnloader)
            {
                if (this.transferUnloadBeltToAutoUnloaderTask == null
                    || this.transferUnloadBeltToAutoUnloaderTask.Status != TaskStatus.Running)
                {
                    this.transferUnloadBeltToAutoUnloaderTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("出料段到收板机线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                ExcuteResult ret = this.transportController.TransferUnloadBeltToAutoUnloader();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(100);
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:


                                        break;
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"出料段到收板机线程：{ex.Message}");
                        }
                    });
                    this.transferUnloadBeltToAutoUnloaderTask.ConfigureAwait(false);
                }
            }

            #endregion
        }
